<script setup lang="ts">definePageMeta({layout:'app'});import type {Session} from '~/types';const view=ref<'agenda'|'week'|'month'>('month');const start=ref(new Date().toISOString().slice(0,10));const sessions=ref<Session[]>([]);const load=async()=>{const d=new Date(start.value);const end=new Date(d);end.setDate(end.getDate()+(view.value==='agenda'?14:view.value==='week'?7:35));sessions.value=(await api<any>(`/sessions?from=${start.value}&to=${end.toISOString().slice(0,10)}`)).data||[]};onMounted(load);watch([view,start],load);const days=computed(()=>Array.from({length:view.value==='month'?35:view.value==='week'?7:14},(_,i)=>{const d=new Date(start.value);d.setDate(d.getDate()+i);return d.toISOString().slice(0,10)}))</script>
<template><div class="workhead"><div><p class="eyebrow">SCHEDULE</p><h1>行事曆</h1></div><div class="toolbar"><input v-model="start" type="date"><button v-for="v in ['agenda','week','month']" :key="v" :class="['button',view===v?'':'ghost']" @click="view=v as any">{{v==='agenda'?'議程':v==='week'?'週':'月'}}</button></div></div><div class="calendar"><div v-for="d in days" :key="d" class="day"><b>{{d.slice(5)}}</b><NuxtLink v-for="s in sessions.filter(x=>x.service_date===d)" :key="s.id" class="event" to="/app">{{s.start_time}} {{s.title}}</NuxtLink></div></div></template>
